def _decimal_int(text: str) -> int | None:
    # 进程级整数转换保护（PEP 682）下，超过位数上限的十进制文本折叠为 None：
    # 调用方按既有非法/不存在语义拒绝（400 或 404），连接保持可用。
    try:
        return int(text)
    except ValueError:
        return None


def _audit_json_int(text: str) -> int:
    # 审计序号接受任意长度合法整数：超出全局 int↔str 位数保护的值折叠为
    # 超存储范围哨兵，由存在性判定按缺失处理（404/not_found）；
    # 不关闭全局转换保护，也不让解析异常断连。
    try:
        return int(text)
    except ValueError:
        return INT64_MAX + 1 if not text.startswith("-") else -1
